function Finder:StartFingerprint(route, definition)
    if self.fingerprintRoute == route and self.fingerprintDefinition == definition then return end
    self:CancelTimer("fingerprintTimer")
    self.fingerprintRoute, self.fingerprintDefinition, self.revision = route, definition, nil
    self.fingerprintJob = nil
    if not definition then return end
    local job = P.NewFingerprintJob(definition)
    self.fingerprintJob = job
    local function run()
        if self.fingerprintJob ~= job or not self:IsEnabled() then return end
        local started = debugprofilestop and debugprofilestop() or 0
        local done, digest
        for _ = 1, 4 do
            done, digest = job:Step(64)
            if done or (debugprofilestop and debugprofilestop() - started >= 1) then break end
        end
        if APR.FinishPerformanceSample then APR:FinishPerformanceSample("PartyFinderFingerprint", started) end
        if done then
            self.revision, self.fingerprintJob = digest, nil
            self.localDirty = true
            if self.searchWanted then
                self:Search()
            else
                self:QueueStateRefresh(true)
                self:Notify()
            end
        else
            self:SetTimer("fingerprintTimer", 0, run)
        end
    end--[[APR_DIAG]]
    run = APRTrace("APR-Core/features/group/PartyFinder.lua:332:run#25", run)--[[/APR_DIAG]]
    self:SetTimer("fingerprintTimer", 0, run)
end--[[APR_DIAG]]
